// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    function setUp() public { c = new SimpleWallet(); }

    function testFuzz_property(uint256 amount) public {
        vm.deal(address(c), 10 ether);
        uint256 value = bound(amount, 0, address(c).balance);
        Reverter r = new Reverter();
        vm.prank(c.owner());
        bool ok;
        try c.sendMoney(address(r), value) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}
